INSERT INTO `announcement` VALUES (1,'系统维护通知','	今晚 22:00 - 23:00 系统进行维护，期间可能无法访问，请谅解。','WARNING',1,1,'2026-05-11 16:30:54','2026-05-11 19:38:04'),(2,'	系统升级通知','亲爱的用户，系统将于今晚 23:00 - 次日 02:00 进行升级维护，期间可能无法访问，请谅解。','WARNING',1,1,'2026-05-11 19:52:39','2026-05-11 20:05:28'),(3,'春节放假通知','春节期间系统正常运营，客服将于1月28日-2月4日暂停服务，祝大家新春快乐！','INFO',1,10,'2026-01-20 10:00:00','2026-05-25 14:05:37'),(4,'新版功能上线公告','健康社区新增“热门推荐”功能，勋章系统新增“自律王者”勋章，欢迎体验！','SUCCESS',1,20,'2026-02-10 14:30:00','2026-05-25 14:05:37'),(5,'系统维护通知','系统将于3月15日凌晨02:00-06:00进行维护升级，期间可能无法访问，敬请谅解。','WARNING',1,5,'2026-03-10 09:00:00','2026-05-25 14:05:37'),(6,'健康打卡活动上线','#21天自律挑战赛# 正式开启！连续打卡21天可获得“自律王者”勋章及专属称号！','SUCCESS',1,30,'2026-03-20 16:00:00','2026-05-25 14:05:37'),(7,'服务器迁移通知','为提升访问体验，系统将于4月5日迁移至新服务器，预计停机4小时。','WARNING',1,3,'2026-04-01 11:00:00','2026-05-25 14:05:37'),(8,'饮食记录功能升级','饮食记录新增七项营养素（蛋白质、脂肪、碳水等）追踪功能，更精准管理每日营养摄入！','SUCCESS',1,25,'2026-04-15 15:00:00','2026-05-25 14:05:37'),(9,'五一假期运营公告','五一期间系统正常运营，客服团队轮班值守，如有问题请留言。','INFO',1,15,'2026-04-28 10:30:00','2026-05-25 14:05:37'),(10,'AI食物识别优化','百度AI菜品识别功能已升级，识别准确率提升30%，支持更多菜品类型！','SUCCESS',1,22,'2026-05-01 09:00:00','2026-05-25 14:05:37'),(11,'母亲节特别活动','5月10日母亲节，分享与妈妈的健康故事，有机会获得定制健康礼包！','INFO',0,8,'2026-05-05 12:00:00','2026-05-25 14:05:37'),(12,'敏感词过滤规则更新','为维护社区环境，敏感词库已更新，请用户遵守社区规范。','WARNING',1,2,'2026-05-15 14:00:00','2026-05-25 14:05:37'),(13,'健康分析报告功能上线','新增“健康综合评分”和“智能洞察建议”功能，为您提供个性化健康分析！','SUCCESS',1,28,'2026-05-18 16:30:00','2026-05-25 14:05:37'),(14,'端午节放假通知','端午节期间（5月31日-6月2日）客服在线时间调整为10:00-18:00，祝大家端午安康！','INFO',1,12,'2026-05-20 09:00:00','2026-05-25 14:05:37');
