DROP TABLE IF EXISTS `health_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `health_record` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `height` double DEFAULT NULL,
  `weight` double DEFAULT NULL,
  `bmi` double DEFAULT NULL,
  `record_date` date NOT NULL COMMENT '记录日期',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `body_fat` double DEFAULT NULL,
  `chest` double DEFAULT NULL,
  `waist` double DEFAULT NULL,
  `hip` double DEFAULT NULL,
  `thigh` double DEFAULT NULL,
  `resting_heart_rate` int(11) DEFAULT NULL COMMENT '静息心率(次/分)',
  `sleep_duration` double DEFAULT NULL,
  `water_intake` int(11) DEFAULT NULL COMMENT '饮水量(ml)',
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `health_record_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=117 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='健康档案表';
