--
-- Table structure for table `post`
--

DROP TABLE IF EXISTS `post`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `post` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL COMMENT '发布者ID',
  `content` text NOT NULL COMMENT '动态内容',
  `images` varchar(2000) DEFAULT NULL,
  `type` varchar(20) DEFAULT 'SHARE' COMMENT '类型：SHARE-分享, CHECKIN-打卡, SPORT-运动, DIET-饮食',
  `like_count` int(11) DEFAULT '0' COMMENT '点赞数',
  `comment_count` int(11) DEFAULT '0' COMMENT '评论数',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `sync_health_data` int(11) DEFAULT NULL,
  `tag` varchar(255) DEFAULT NULL,
  `is_featured` int(11) DEFAULT '0' COMMENT '0:否, 1:加精',
  `is_pinned` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `post_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=709 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='动态表';
/*!40101 SET character_set_client = @saved_cs_client */;

