--
-- Table structure for table `user`
--

DROP TABLE IF EXISTS `user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `user` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(255) NOT NULL,
  `password` varchar(255) NOT NULL,
  `nickname` varchar(255) DEFAULT NULL,
  `role` varchar(255) DEFAULT NULL,
  `current_height` double DEFAULT NULL,
  `current_weight` double DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `target_weight` double DEFAULT NULL,
  `body_fat` double DEFAULT NULL,
  `chest` double DEFAULT NULL,
  `waist` double DEFAULT NULL,
  `hip` double DEFAULT NULL,
  `thigh` double DEFAULT NULL,
  `resting_heart_rate` int(11) DEFAULT NULL COMMENT '静息心率(次/分)',
  `sleep_duration` double DEFAULT NULL,
  `water_intake` int(11) DEFAULT NULL COMMENT '饮水量(ml)',
  `age` int(11) DEFAULT NULL,
  `gender` varchar(255) DEFAULT NULL,
  `avatar` varchar(255) DEFAULT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `open_id` varchar(255) DEFAULT NULL,
  `follow_count` int(11) NOT NULL DEFAULT '0' COMMENT '关注数',
  `fans_count` int(11) NOT NULL DEFAULT '0' COMMENT '粉丝数',
  `mutual_count` int(11) NOT NULL DEFAULT '0' COMMENT '互关数',
  `target_body_fat` double DEFAULT NULL,
  `is_banned` int(11) DEFAULT NULL,
  `ban_end_time` datetime DEFAULT NULL COMMENT '禁言结束时间',
  `status` int(11) DEFAULT NULL,
  `activity_level` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  UNIQUE KEY `phone` (`phone`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=616 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户表';
/*!40101 SET character_set_client = @saved_cs_client */;

