--
-- Table structure for table `user_follow`
--

DROP TABLE IF EXISTS `user_follow`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `user_follow` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `follower_id` int(11) NOT NULL COMMENT '关注者ID',
  `followed_id` int(11) NOT NULL COMMENT '被关注者ID',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '状态: 1-关注, 2-互关, 3-已取消, 4-拉黑',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '首次关注时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_follow` (`follower_id`,`followed_id`),
  KEY `idx_follower_status` (`follower_id`,`status`),
  KEY `idx_followed_status` (`followed_id`,`status`),
  KEY `idx_create_time` (`create_time`),
  CONSTRAINT `user_follow_ibfk_1` FOREIGN KEY (`follower_id`) REFERENCES `user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `user_follow_ibfk_2` FOREIGN KEY (`followed_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户关注关系表';
/*!40101 SET character_set_client = @saved_cs_client */;

