DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_block_user`(
    IN p_follower_id INT,
    IN p_blocked_id INT
)
BEGIN
    INSERT INTO `user_follow` (`follower_id`, `followed_id`, `status`)
    VALUES (p_follower_id, p_blocked_id, 4)
    ON DUPLICATE KEY UPDATE 
        `status` = 4, `update_time` = NOW();
    
    -- 如果对方关注我，取消对方的关注状态
    UPDATE `user_follow` 
    SET `status` = 3, `update_time` = NOW()
    WHERE `follower_id` = p_blocked_id AND `followed_id` = p_follower_id;
    
    -- 更新统计
    CALL `sp_update_user_follow_stats`(p_follower_id);
    CALL `sp_update_user_follow_stats`(p_blocked_id);
END ;;
DELIMITER ;
