/*!50003 DROP PROCEDURE IF EXISTS `sp_follow_user` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_follow_user`(
    IN p_follower_id INT,
    IN p_followed_id INT
)
BEGIN
    -- 不能关注自己
    IF p_follower_id = p_followed_id THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '不能关注自己';
    END IF;
    
    -- 插入或更新关注关系
    INSERT INTO `user_follow` (`follower_id`, `followed_id`, `status`)
    VALUES (p_follower_id, p_followed_id, 1)
    ON DUPLICATE KEY UPDATE 
        `status` = IF(`status` = 3, 1, `status`),
        `update_time` = NOW();
    
    -- 检查是否互关
    UPDATE `user_follow` SET `status` = 2
    WHERE `follower_id` = p_followed_id AND `followed_id` = p_follower_id AND `status` = 1;
    
    UPDATE `user_follow` SET `status` = 2
    WHERE `follower_id` = p_follower_id AND `followed_id` = p_followed_id 
    AND EXISTS (
        SELECT 1 FROM `user_follow` 
        WHERE `follower_id` = p_followed_id AND `followed_id` = p_follower_id AND `status` = 1
    );
    
    -- 更新 user 表的统计字段
    CALL `sp_update_user_follow_stats`(p_follower_id);
    CALL `sp_update_user_follow_stats`(p_followed_id);
END ;;
DELIMITER ;
