/*!50003 DROP PROCEDURE IF EXISTS `sp_update_user_follow_stats` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_update_user_follow_stats`(
    IN p_user_id INT
)
BEGIN
    UPDATE `user` SET
        `follow_count` = (SELECT COUNT(*) FROM `user_follow` WHERE `follower_id` = p_user_id AND `status` IN (1, 2)),
        `fans_count` = (SELECT COUNT(*) FROM `user_follow` WHERE `followed_id` = p_user_id AND `status` IN (1, 2)),
        `mutual_count` = (SELECT COUNT(*) FROM `user_follow` WHERE `follower_id` = p_user_id AND `status` = 2)
    WHERE `id` = p_user_id;
END ;;
DELIMITER ;
